"""Adversarial verification of planbench_metrics.trace_review."""

from __future__ import annotations

import numpy as np
import pandas as pd

from planbench_decision.self_check import exists
from planbench_metrics.trace_review import (
    TRACE_REVIEW_CODES,
    summarise_trace,
    trace_advice,
)

DT = 0.05


def _series(value, rows):
    if isinstance(value, (int, float)):
        return np.full(rows, float(value))
    a = np.asarray(value, dtype=float)
    assert a.size == rows, (a.size, rows)
    return a


def frame(*, rows=100, v=0.5, omega=0.0, clearance=1.0, latency=3.0, events=None, dt=DT):
    speed = _series(v, rows)
    turn = _series(omega, rows)
    theta = np.cumsum(turn) * dt
    x = np.cumsum(speed * np.cos(theta)) * dt
    y = np.cumsum(speed * np.sin(theta)) * dt
    column = [None] * rows
    for i, name in (events or {}).items():
        column[i] = name
    return pd.DataFrame(
        {
            "t": np.arange(rows) * dt,
            "x": x,
            "y": y,
            "theta": theta,
            "v": speed,
            "omega": turn,
            "clearance_m": _series(clearance, rows),
            "planner_latency_ms": _series(latency, rows),
            "event": column,
        }
    )


# ---------------------------------------------------------------- fixtures
# one per declared code; each is meant to make exactly that rule fire.

def f_collision():
    return frame(
        rows=100,
        clearance=np.concatenate([np.full(40, 1.5), np.linspace(1.5, 0.0, 60)]),
        events={99: "collision"},
    )


def f_no_path():
    return frame(rows=20, v=0.0, events={19: "no_path"})


def f_no_terminal_event():
    return frame(rows=100)


def f_stalled():
    # stops at index 40 (t=2.0), file runs to t=4.95 -> stalled 2.95 s
    return frame(rows=100, v=np.concatenate([np.full(40, 0.5), np.zeros(60)]), events={99: "stuck"})


def f_spinning():
    return frame(
        rows=100,
        v=np.concatenate([np.full(40, 0.5), np.zeros(60)]),
        omega=np.concatenate([np.zeros(40), np.full(60, 0.4)]),
        events={99: "stuck"},
    )


def f_timeout_driving():
    return frame(rows=100, v=0.4, events={99: "timeout"})


def f_oscillating():
    # alternate sign of omega every sample -> 99 reversals over ~5 s
    omega = np.where(np.arange(100) % 2 == 0, 0.5, -0.5)
    return frame(rows=100, v=0.5, omega=omega, events={99: "goal_reached"})


def f_clearance_collapse():
    # last 2 s give away most of the margin, ends at the minimum, no collision
    return frame(
        rows=100,
        clearance=np.concatenate([np.full(60, 1.5), np.linspace(1.5, 0.05, 40)]),
        events={99: "timeout"},
    )


def f_margin_spent():
    # min/max <= 0.10 but no collapse in the final window (flat tail)
    clearance = np.concatenate([np.full(20, 2.0), np.full(80, 0.15)])
    return frame(rows=100, clearance=clearance, events={99: "goal_reached"})


def f_replan():
    latency = np.full(100, 3.0)
    latency[30] = 210.0
    return frame(rows=100, latency=latency, events={30: "replan", 99: "goal_reached"})


def f_latency_over_period():
    return frame(rows=100, latency=80.0, events={99: "goal_reached"})


FIXTURES = {
    "TR_COLLISION": f_collision,
    "TR_NO_PATH": f_no_path,
    "TR_NO_TERMINAL_EVENT": f_no_terminal_event,
    "TR_STALLED_BEFORE_END": f_stalled,
    "TR_SPINNING_IN_PLACE": f_spinning,
    "TR_TIMEOUT_STILL_DRIVING": f_timeout_driving,
    "TR_OSCILLATING": f_oscillating,
    "TR_CLEARANCE_COLLAPSE": f_clearance_collapse,
    "TR_MARGIN_SPENT": f_margin_spent,
    "TR_REPLAN_COST": f_replan,
    "TR_LATENCY_OVER_SAMPLE_PERIOD": f_latency_over_period,
}


def main() -> None:
    print("=== declared codes:", len(TRACE_REVIEW_CODES))
    for c in TRACE_REVIEW_CODES:
        print("   ", c)

    fired: set[str] = set()
    unresolved: list[str] = []
    blocking_no_do_not: list[str] = []
    print("\n=== per-rule firing + citation resolution")
    for code, builder in FIXTURES.items():
        summary = summarise_trace(builder(), candidate_id="cand", episode_context_id=code)
        advice = trace_advice(summary)
        got = {a.code for a in advice}
        fired |= got
        hit = code in got
        line = f"{code:32s} fired={hit!s:5s} all={sorted(got)}"
        print(line)
        if not hit:
            print(f"    !! {code} DID NOT FIRE on its own fixture")
        for a in advice:
            ok = exists(summary, a.field_path)
            if not ok:
                unresolved.append(f"{a.code} -> {a.field_path} (fixture {code})")
            if a.severity == "blocking" and not a.do_not:
                blocking_no_do_not.append(a.code)
            print(f"      {a.code:32s} sev={a.severity:10s} path={a.field_path:42s} resolves={ok}")

    print("\n=== coverage")
    print("declared but never fired (DEAD):", sorted(set(TRACE_REVIEW_CODES) - fired))
    print("fired but not declared        :", sorted(fired - set(TRACE_REVIEW_CODES)))
    print("unresolvable citations        :", unresolved)
    print("blocking without do_not       :", sorted(set(blocking_no_do_not)))


if __name__ == "__main__":
    main()

