print("=== 1. every declared code fires from a hand-built minimal source ===")
emitted_any: set[str] = set()
for code in REPORT_ADVICE_CODES:
    case = CASES.get(code)
    if case is None:
        note(False, f"{code}: NO CASE BUILT")
        continue
    src = case
    out = report_advice(src)
    emitted_any |= {a.code for a in out}
    hit = [a for a in out if a.code == code]
    if not hit:
        note(False, f"{code}: did not fire; got {sorted({a.code for a in out})}")
