print(f"  emitted: {sorted({a.code for a in out})}")
print("  -> RP_NO_CARD_NO_WINNER present:", "RP_NO_CARD_NO_WINNER" in {a.code for a in out})

print()
print("=== 2. dead codes: declared but never emitted by any input tried ===")
stored: set[str] = set()
for p in (GATED, CARDED, TIED):
    d = json.loads(p.read_text())
    stored |= {a.code for a in report_advice(build_reporting_source(d))}
