print("  NOT fired on stored runs:", sorted(set(REPORT_ADVICE_CODES) - stored))
reachable = emitted_any | stored
dead = sorted(set(REPORT_ADVICE_CODES) - reachable)
note(not dead, f"dead declared codes: {dead}")

