note(
    emitted_literals == set(REPORT_ADVICE_CODES),
    f"declared == emitted literals (declared-only={sorted(set(REPORT_ADVICE_CODES)-emitted_literals)}, "
    f"emitted-only={sorted(emitted_literals-set(REPORT_ADVICE_CODES))})",
)

print()
print("=== 3. never raises ===")
BAD: list[Any] = [
