    None,
    [],
    "not a source",
    42,
    {"report": None, "card": None},
    {"report": {"candidates": "not a list"}},
    {"report": {"candidates": [None]}},
    {"report": {"candidates": [{"gates": "nope"}]}},
    {"report": {"candidates": {"a": 1}}},
    {"report": {"sample": 5}, "card": None},
    {"report": {}, "card": "not a card"},
    {"report": {}, "card": 7},
    {"report": {}, "card": {"evidence": "nope"}},
    {"report": {}, "card": {"evidence": {"ci95": [1]}}},
    {"report": {}, "card": {"evidence": {"ci95": ["a", "b"], "delta_u_vs_second": 1}}},
    {"report": {}, "card": {"recommended": "x", "status": "NEAR_EQUIVALENT"}},
    {"report": {}, "card": {"approval": "x"}},
    {"report": {"identity": "x"}, "card": {"status": "X"}},
    {"report": {"sample": {"n_episodes": 0}, "candidates": [{"success_rate": 1.0}]}},
    {"report": {"sample": {"n_episodes": -3}, "candidates": [{"success_rate": 1.0}]}},
    {"report": {"candidates": [{"n_distinct_episodes": True}]}},
    {"report": {"candidates": [{"gates": {"G4": "screened_on_host"}}]}},
    {"report": {"candidates": [{"gates": {"G5": {"status": None}}}]}},
    {"report": {"why_no_card": {"nested": "dict"}}, "card": None},
]
for i, bad in enumerate(BAD):
    try:
        out = report_advice(bad)
        ok = isinstance(out, tuple)
        note(ok, f"input[{i}] {str(bad)[:60]!r:64} -> {len(out)} advice")
    except Exception as exc:  # noqa: BLE001
        note(False, f"input[{i}] {str(bad)[:60]!r} RAISED {type(exc).__name__}: {exc}")

print()
print("=== 4. blocking advice always names a do_not; kind always 'reporting' ===")
all_advice: list[tuple[str, Advice]] = []
for name, case in CASES.items():
    for a in report_advice(case):
        all_advice.append((name, a))
for p in (GATED, CARDED, TIED):
    d = json.loads(p.read_text())
    for a in report_advice(build_reporting_source(d)):
        all_advice.append((p.parent.name, a))
missing_donot = sorted({a.code for _, a in all_advice if a.severity == "blocking" and not a.do_not.strip()})
note(not missing_donot, f"blocking without do_not: {missing_donot}")
no_do = sorted({a.code for _, a in all_advice if not a.do.strip()})
note(not no_do, f"advice without do: {no_do}")
bad_kind = sorted({(a.code, a.kind) for _, a in all_advice if a.kind != "reporting"})
note(not bad_kind, f"non-reporting kind: {bad_kind}")
frozen_ok = True
sample_advice = all_advice[0][1]
try:
    sample_advice.code = "X"  # type: ignore[misc]
    frozen_ok = False
except Exception:
    pass
note(frozen_ok, "Advice objects are frozen")
print(f"  total advice objects inspected: {len(all_advice)}")

print()
print("=== 5. exhaustive citation resolution across every source tried ===")
unresolved: list[str] = []
for name, case in CASES.items():
    for a in report_advice(case):
        if not exists(case, a.field_path):
            unresolved.append(f"{name}/{a.code}:{a.field_path}")
for p in (GATED, CARDED, TIED):
    src = build_reporting_source(json.loads(p.read_text()))
    for a in report_advice(src):
        if not exists(src, a.field_path):
            unresolved.append(f"{p.parent.name}/{a.code}:{a.field_path}")
